import {today,addDays,daysUntil,norm,shopping,seed} from './domain.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=JSON.parse(localStorage.getItem('kitchen-demo')||'null')||seed(),page='overview',start=today(),end=addDays(today(),6),client=null,user=null,version=0,busy=false,stream=null,scanTimer=null;
const icon=n=>`<svg class="icon" aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><use href="icons.svg#${n}"></use></svg>`;
const categories=['Carbs','Protein','Vegetables','Fruit','Dairy','Fats','Other'],units=['g','ml','pcs'];
const options=(values,current)=>values.map(x=>`<option ${x===current?'selected':''}>${esc(x)}</option>`).join('');
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
function modal(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog').showModal()}
function stopCamera(){clearTimeout(scanTimer);stream?.getTracks().forEach(t=>t.stop());stream=null}$('#close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('close',stopCamera);
async function mutate(fn){if(busy)return toast('Please wait for the current save.');if(client&&!user)return toast('Sign in to save your kitchen.');busy=true;const before=structuredClone(state);try{fn();if(client){const {data,error}=await client.from('kitchen_data').update({data:state,version:version+1}).eq('owner_id',user.id).eq('version',version).select('version');if(error)throw error;if(!data.length)throw Error('This kitchen changed in another tab. Reload before editing.');version++}else localStorage.setItem('kitchen-demo',JSON.stringify(state));render();return true}catch(e){state=before;toast('Could not save: '+e.message);return false}finally{busy=false}}
function setPage(p){page=p;render()}
$('#nav').onclick=e=>{const b=e.target.closest('[data-page]');if(b)setPage(b.dataset.page)};
function heading(title,subtitle,action=''){return `<div class="heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`}
const foodEmoji=x=>x.emoji||({Carbs:'🌾',Protein:'🫘',Vegetables:'🥬',Fruit:'🍋',Dairy:'🥛',Fats:'🫒'}[x.category]||'🥫');
function foodRow(x,editable=false){const d=daysUntil(x.expiry);return `<div class="food-row"><div class="food-icon">${icon(({Carbs:'wheat',Protein:'bean',Vegetables:'leaf',Fruit:'citrus',Dairy:'milk',Fats:'sprout'})[x.category]||'package')}</div><div class="food-info"><strong>${esc(x.name)}</strong><small>${x.quantity} ${esc(x.unit)} · ${esc(x.location)}</small></div><div class="row-end"><span class="pill ${d<0?'red':d<=state.notifyDays?'warm':''}">${d<0?'Expired':d===0?'Today':d===1?'Tomorrow':`In ${d} days`}</span>${editable?`<div><button data-edit-food="${x.id}">Edit</button><button data-delete-food="${x.id}" aria-label="Remove ${esc(x.name)}">${icon('x')}</button></div>`:''}</div></div>`}
function conflicts(m){return state.preferences.flatMap(p=>[...p.avoid.split(',').map(norm).filter(Boolean),...(p.diet==='vegetarian'?['chicken','beef','fish','pork']:p.diet==='vegan'?['chicken','beef','fish','pork','dairy','egg','yogurt','cream']:[])].filter(t=>norm(m.tags+' '+m.ingredients.map(i=>i.name).join(' ')).includes(t)).map(t=>`${p.name}: ${t}`))}
function mealCard(m){const warnings=conflicts(m);return `<article class="meal" draggable="true" data-drag="${m.id}"><div class="meal-visual">${icon('utensils')}</div><div class="meal-body"><h3>${esc(m.name)}</h3><small>${m.servings} servings · ${m.ingredients.length} ingredients</small><p>${m.ingredients.map(i=>esc(i.name)).join(' · ')}</p>${m.tags.split(',').filter(Boolean).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}${warnings.length?`<div class="notice">Check preferences: ${esc(warnings.join(', '))}</div>`:''}<div class="meal-actions"><button class="primary" data-schedule="${m.id}">${icon('plus')} Plan meal</button><button data-edit-meal="${m.id}">Edit</button><button data-delete-meal="${m.id}" aria-label="Delete meal">${icon('x')}</button></div></div></article>`}
function overview(){const soon=state.inventory.filter(x=>daysUntil(x.expiry)<=state.notifyDays).sort((a,b)=>a.expiry.localeCompare(b.expiry)),planned=state.plan.filter(p=>p.date>=today()&&p.date<=addDays(today(),6));return heading('A happier kitchen starts here.','A little overview of what’s fresh, what’s planned, and what’s next.',`<button class="primary" data-action="add-food">${icon('plus')} Add food</button>`)+`<section class="hero"><div><p class="eyebrow" style="margin:0 0 12px">LESS WASTE, MORE GOOD FOOD</p><h2>Good meals begin with<br>what you already have.</h2><p>Give the food in your fridge a delicious next chapter.<br>Plan a few meals and we’ll take care of the list.</p><button class="primary" data-go="planner">Let’s plan something ${icon('arrow-up-right')}</button></div><div class="hero-art" aria-hidden="true">${icon('leaf')}${icon('citrus')}${icon('sprout')}</div></section><div class="stats"><div class="stat"><div class="stat-top">In your pantry <span>${icon('package')}</span></div><strong>${state.inventory.length}</strong><small>food items, full of possibilities</small></div><div class="stat"><div class="stat-top">Use soon <span>${icon('clock')}</span></div><strong>${soon.length}</strong><small>within ${state.notifyDays} days, or expired</small></div><div class="stat"><div class="stat-top">Meals planned <span>${icon('calendar-days')}</span></div><strong>${planned.length}</strong><small>over the next seven days</small></div><div class="stat"><div class="stat-top">Shopping list <span>${icon('shopping-basket')}</span></div><strong>${shopping(state,start,end).length}</strong><small>ingredients left to pick up</small></div></div><div class="grid-two"><section class="panel"><div class="panel-head"><h2>A little time-sensitive</h2><button class="text-button" data-go="inventory">View pantry ${icon('arrow-right')}</button></div>${soon.length?soon.slice(0,4).map(x=>foodRow(x)).join(''):'<div class="empty">Everything is looking fresh.</div>'}</section><section class="panel"><div class="panel-head"><h2>On the menu</h2><button class="text-button" data-go="planner">View planner ${icon('arrow-right')}</button></div>${planned.length?planned.slice(0,4).map(p=>`<div class="food-row"><div class="food-icon">${icon('utensils')}</div><div><h3>${esc(state.meals.find(m=>m.id===p.mealId)?.name)}</h3><small>${esc(p.date)} · ${p.slot} · ${p.servings} servings</small></div></div>`).join(''):`<div class="empty"><div class="empty-icon">${icon('utensils')}</div><h3>A fresh week, a blank plate.</h3><p>Your favorite meals are ready when you are.</p><button data-go="planner">Plan your first meal ${icon('arrow-right')} </button></div>`}</section></div>`}
function inventory(){return heading('Your pantry, in good order.','Know what you have. Make the most of every ingredient.',`<button class="primary" data-action="add-food">${icon('plus')} Add food</button>`)+`<div class="toolbar"><input type="search" id="food-search" placeholder="Search your pantry…" aria-label="Search pantry"><select id="food-category" aria-label="Filter category"><option>All categories</option>${options(categories)}</select><select id="food-sort" aria-label="Sort pantry"><option value="expiry">Expiry date</option><option value="name">Name</option></select><button data-action="scan">${icon('scan-barcode')} Scan barcode</button></div><section class="panel" id="inventory-list"></section>`}
function inventoryList(){const q=norm($('#food-search').value),c=$('#food-category').value,sort=$('#food-sort').value;$('#inventory-list').innerHTML=state.inventory.filter(x=>norm(x.name).includes(q)&&(c==='All categories'||c===x.category)).sort((a,b)=>a[sort].localeCompare(b[sort])).map(x=>foodRow(x,true)).join('')||'<div class="empty">No food found. Add something fresh.</div>'}
function range(){return `<div class="date-controls"><label>From<input type="date" id="start" value="${start}" required></label><label>Until<input type="date" id="end" value="${end}" required></label></div>`}
function planner(){let dates=[];for(let d=start;d<=end&&dates.length<31;d=addDays(d,1))dates.push(d);return heading('Make room for good meals.','Drag a favorite onto a day, or use “Plan meal” to choose a date.')+`<div class="toolbar">${range()}<button data-go="meals">${icon('plus')} Create a meal</button></div><div class="meal-tray">${state.meals.map(m=>`<div class="draggable" draggable="true" data-drag="${m.id}">${esc(m.emoji)} <b>${esc(m.name)}</b><br><button class="text-button" data-schedule="${m.id}">Plan meal +</button></div>`).join('')}</div><div class="calendar-wrap"><div class="calendar" style="grid-template-columns:repeat(${Math.min(dates.length,7)},minmax(145px,1fr))">${dates.map(d=>`<section class="day"><h3>${new Date(d+'T12:00').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'})}</h3>${['Lunch','Dinner'].map(slot=>`<div class="slot" data-date="${d}" data-slot="${slot}"><small>${slot}</small>${state.plan.filter(p=>p.date===d&&p.slot===slot).map(p=>`<div class="planned">${esc(state.meals.find(m=>m.id===p.mealId)?.name||'Deleted meal')}<br><small>${p.servings} servings</small><br><button data-remove-plan="${p.id}">Remove</button></div>`).join('')}</div>`).join('')}</section>`).join('')}</div></div>`}
function shoppingPage(){const items=shopping(state,start,end);return heading('A list with a little less guesswork.','Only what’s missing for your planned meals.',`<button data-action="export">${icon('download')} Export list</button>`)+`<div class="toolbar">${range()}</div><p class="section-note">Stock is allocated once, in meal date order. Expired food is excluded. Categories like Carbs can use any matching pantry item in the same unit. g, ml and pieces are kept separate.</p><section class="panel">${items.length?items.map(x=>{const key=x.name+'|'+x.unit;return `<label class="shopping-row ${state.checks.includes(key)?'checked':''}"><input type="checkbox" data-check="${esc(key)}" ${state.checks.includes(key)?'checked':''}><span>${esc(x.name)} ${x.group?'<small>· choose an ingredient from this category</small>':''}</span><b>${Math.ceil(x.quantity*100)/100} ${esc(x.unit)}</b></label>`}).join(''):'<div class="empty">All set! Nothing missing for this interval.<p>Add meals in the planner to build your list.</p></div>'}</section>`}
function preferences(){return heading('Two people. One happy kitchen.','Keep your tastes and dietary preferences close at hand.')+`<form id="prefs"><div class="grid-two">${state.preferences.map((p,i)=>`<section class="panel"><h2>${i?'Your husband':'You'}</h2><br><label>Name<input name="name${i}" value="${esc(p.name)}" required></label><br><label>Diet<select name="diet${i}">${options(['','vegetarian','vegan','pescatarian','omnivore'],p.diet)}</select></label><br><label>Avoid ingredients or tags (comma separated)<input name="avoid${i}" value="${esc(p.avoid)}" placeholder="e.g. peanuts, dairy, mushrooms"></label><br><label>Other preferences<textarea name="notes${i}" placeholder="Favorite flavors, portion preferences…">${esc(p.notes)}</textarea></label></section>`).join('')}</div><div class="notice">Preference warnings use the ingredient names and tags you enter. Check labels and substitutions yourself for allergies. Notes are saved for reference.</div><div class="panel"><label>Days before expiry to show reminders<input type="number" name="notifyDays" min="0" max="30" value="${state.notifyDays}" required></label><p class="section-note">Expiry reminders appear in the app. Browser notifications are checked while the app is open; closed-app push/email delivery is not configured.</p><button type="button" data-action="notifications">Enable browser notifications</button></div><div><button class="primary">Save preferences</button></div></form><section class="panel" style="margin-top:24px"><h2>Data & connection</h2><p>${client?'Connected to Supabase. Your data is protected by database policies.':'Local demo: changes stay in this browser. Connect Supabase for your private kitchen across devices.'}</p><button data-action="connect">${user?'Account & connection':'Connect Supabase'}</button> <button data-action="backup">Download data backup</button></section>`}
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#breadcrumb').textContent={overview:'Your kitchen, at a glance',inventory:'Kitchen / My pantry',meals:'Kitchen / Favorite meals',planner:'Kitchen / Meal planner',shopping:'Kitchen / Shopping list',preferences:'Kitchen / Household & settings'}[page];$('#mode').textContent=user?'Private kitchen':client?'Sign in required':'Local demo';$('#account').textContent=user?'Account':client?'Sign in':'Connect Supabase';if(client&&!user){$('#app').innerHTML=heading('Your kitchen is just for you.','Sign in with the account you created in Supabase.',`<button class="primary" data-action="connect">Sign in</button>`);return}$('#app').innerHTML=page==='overview'?overview():page==='inventory'?inventory():page==='meals'?heading('The meals you come back to.','Your favorites, with room for a little flexibility.',`<button class="primary" data-action="add-meal">${icon('plus')} Add meal</button>`)+`<div class="meal-grid">${state.meals.map(mealCard).join('')||'<div class="empty">Add your first favorite meal.</div>'}</div>`:page==='planner'?planner():page==='shopping'?shoppingPage():preferences();if(page==='inventory'){inventoryList();['#food-search','#food-category','#food-sort'].forEach(s=>$(s).oninput=inventoryList)}if($('#start'))['#start','#end'].forEach(s=>$(s).onchange=()=>{const a=$('#start').value,b=$('#end').value;if(!a||!b||b<a||daysBetween(a,b)>30){toast('Choose an interval from 1 to 31 days.');render();return}start=a;end=b;render()});if($('#prefs'))$('#prefs').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(await mutate(()=>{state.preferences=[0,1].map(i=>({name:f.get('name'+i),diet:f.get('diet'+i),avoid:f.get('avoid'+i),notes:f.get('notes'+i)}));state.notifyDays=Number(f.get('notifyDays'))}))toast('Household preferences saved.')};bindDrag()}
const daysBetween=(a,b)=>(new Date(b)-new Date(a))/86400000;
function foodForm(id,barcode=''){const x=state.inventory.find(x=>x.id===id)||{name:'',quantity:1,unit:'pcs',category:'Other',expiry:addDays(today(),7),location:'Pantry'};modal(id?'Edit food':'A fresh addition',`<form id="food-form"><label>Barcode (optional)<div class="toolbar"><input id="barcode" value="${esc(barcode)}" inputmode="numeric" placeholder="Type or scan barcode"><button type="button" id="lookup">Look up</button></div></label><label>Food name<input id="food-name" name="name" value="${esc(x.name)}" maxlength="120" required></label><div class="form-row"><label>Quantity<input name="quantity" type="number" min="0.01" step="any" value="${x.quantity}" required></label><label>Unit<select name="unit">${options(units,x.unit)}</select></label></div><div class="form-row"><label>Category<select name="category">${options(categories,x.category)}</select></label><label>Storage<select name="location">${options(['Pantry','Fridge','Freezer'],x.location)}</select></label></div><label>Expiration date<input name="expiry" type="date" value="${x.expiry}" required></label><small>Barcode lookup supplies a name. Check the package for its expiry date.</small><button class="primary">Save food</button></form>`);$('#lookup').onclick=lookup;$('#food-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.quantity=Number(f.quantity);f.name=f.name.trim();if(!f.name)return;if(await mutate(()=>{const item={...f,id:id||crypto.randomUUID(),barcode:$('#barcode').value};if(id)state.inventory[state.inventory.findIndex(x=>x.id===id)]=item;else state.inventory.push(item)}))$('#dialog').close()};if(barcode)lookup()}
async function lookup(){const code=$('#barcode').value.trim();if(!/^\d{8,14}$/.test(code))return toast('Enter a barcode with 8–14 digits.');$('#lookup').disabled=true;try{const r=await fetch(`https://world.openfoodfacts.org/api/v3/product/${code}?fields=product_name`,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Lookup unavailable');const d=await r.json();if(d.product?.product_name){$('#food-name').value=d.product.product_name;toast('Product found. Check quantity and expiry.')}else toast('Product not found. Enter its name manually.')}catch{toast('Could not look up this barcode. Manual entry is available.')}finally{if($('#lookup'))$('#lookup').disabled=false}}
async function scan(){if(!('BarcodeDetector' in window)){foodForm();toast('Camera scanning is unavailable in this browser. Type the barcode or use a USB scanner.');return}modal('Scan a barcode','<video id="camera" autoplay muted playsinline></video><p>Point the camera at the barcode. Camera processing stays on this device.</p><button id="manual">Enter barcode manually</button>');$('#manual').onclick=()=>{stopCamera();$('#dialog').close();foodForm()};try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});$('#camera').srcObject=stream;const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e']});const tick=async()=>{if(!stream)return;try{const result=await detector.detect($('#camera'));if(result.length){const code=result[0].rawValue;stopCamera();$('#dialog').close();foodForm(null,code);return}}catch{}scanTimer=setTimeout(tick,250)};tick()}catch{stopCamera();$('#dialog').close();foodForm();toast('Camera access unavailable. Enter the barcode manually.')}}
function mealForm(id){const m=state.meals.find(x=>x.id===id)||{name:'',emoji:'🍽️',servings:2,tags:'',ingredients:[]};modal(id?'Edit your favorite':'A new favorite',`<form id="meal-form"><label>Meal name<input name="name" value="${esc(m.name)}" required maxlength="120"></label><div class="form-row"><label>Emoji<input name="emoji" value="${esc(m.emoji)}" maxlength="10" required></label><label>Recipe servings<input name="servings" type="number" min="1" max="50" value="${m.servings}" required></label></div><label>Dietary / allergen tags<input name="tags" value="${esc(m.tags)}" placeholder="vegetarian, dairy, gluten"></label><label>Ingredients — one per line<textarea name="ingredients" required placeholder="Pasta | 180 | g&#10;Spinach | 200 | g&#10;@Carbs | 160 | g">${esc(m.ingredients.map(i=>`${i.group?'@':''}${i.name} | ${i.quantity} | ${i.unit}`).join('\n'))}</textarea></label><small>Format: name | quantity | g, ml or pcs.<br>Use @Carbs or @Protein for flexible categories: ${categories.join(', ')}.</small><button class="primary">Save meal</button></form>`);$('#meal-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));let ingredients;try{ingredients=f.ingredients.split('\n').filter(s=>s.trim()).map(line=>{const [name,q,unit]=line.split('|').map(s=>s.trim());if(!name||!(Number(q)>0)||!units.includes(unit)||name.startsWith('@')&&!categories.includes(name.slice(1)))throw Error();return {name:name.replace(/^@/,''),quantity:Number(q),unit,group:name.startsWith('@')}})}catch{return toast('Check each ingredient: name | positive quantity | g, ml or pcs.')}if(await mutate(()=>{const meal={id:id||crypto.randomUUID(),name:f.name.trim(),emoji:f.emoji,tags:f.tags,servings:Number(f.servings),ingredients};if(id)state.meals[state.meals.findIndex(m=>m.id===id)]=meal;else state.meals.push(meal)}))$('#dialog').close()}}
function schedule(id,date=start,slot='Dinner'){const m=state.meals.find(m=>m.id===id);modal('Make it a date',`<form id="schedule"><h3>${esc(m.name)}</h3>${conflicts(m).length?`<div class="notice">Preference check: ${esc(conflicts(m).join(', '))}</div>`:''}<label>Date<input name="date" type="date" value="${date}" required></label><div class="form-row"><label>Meal<select name="slot">${options(['Lunch','Dinner'],slot)}</select></label><label>Servings<input name="servings" type="number" min="1" max="50" value="2" required></label></div><button class="primary">Add to planner</button></form>`);$('#schedule').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(await mutate(()=>state.plan.push({id:crypto.randomUUID(),mealId:id,...f,servings:Number(f.servings)})))$('#dialog').close()}}
function bindDrag(){document.querySelectorAll('[data-drag]').forEach(el=>el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.drag));document.querySelectorAll('.slot').forEach(el=>{el.ondragover=e=>{e.preventDefault();el.classList.add('dragover')};el.ondragleave=()=>el.classList.remove('dragover');el.ondrop=e=>{e.preventDefault();el.classList.remove('dragover');const id=e.dataTransfer.getData('text/plain');if(state.meals.some(m=>m.id===id))schedule(id,el.dataset.date,el.dataset.slot)}})}
function download(name,data,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function notify(request=false){if(!('Notification' in window))return toast('Notifications are unavailable in this browser.');if(request)await Notification.requestPermission();if(Notification.permission!=='granted')return request?toast('Notification permission was not granted. In-app reminders remain available.'):undefined;const soon=state.inventory.filter(x=>daysUntil(x.expiry)<=state.notifyDays);const key='kitchen-notified-'+(user?.id||'demo')+'-'+today();if(soon.length&&!sessionStorage.getItem(key)){new Notification('A little time-sensitive',{body:soon.map(x=>x.name).join(', ')+' — check your pantry.'});sessionStorage.setItem(key,'1')}else if(request)toast('Notifications enabled. Reminders run while the app is open.')}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.go)setPage(d.go);if(d.editFood)foodForm(d.editFood);if(d.editMeal)mealForm(d.editMeal);if(d.schedule)schedule(d.schedule);if(d.removePlan)await mutate(()=>state.plan=state.plan.filter(p=>p.id!==d.removePlan));if(d.deleteFood&&confirm('Remove this pantry item?'))await mutate(()=>state.inventory=state.inventory.filter(x=>x.id!==d.deleteFood));if(d.deleteMeal&&confirm('Delete this meal and its planned entries?'))await mutate(()=>{state.meals=state.meals.filter(x=>x.id!==d.deleteMeal);state.plan=state.plan.filter(p=>p.mealId!==d.deleteMeal)});if(d.action==='add-food')foodForm();if(d.action==='add-meal')mealForm();if(d.action==='scan')scan();if(d.action==='connect')connection();if(d.action==='notifications')notify(true);if(d.action==='backup')download('kitchen-backup.json',JSON.stringify(state,null,2));if(d.action==='export')download('shopping-list.txt',shopping(state,start,end).map(x=>`${x.name}: ${Math.ceil(x.quantity*100)/100} ${x.unit}`).join('\n'),'text/plain')});document.addEventListener('change',e=>{if(e.target.dataset.check){const key=e.target.dataset.check;mutate(()=>state.checks=state.checks.includes(key)?state.checks.filter(x=>x!==key):[...state.checks,key])}});
$('#account').onclick=connection;
function connection(){if(user){modal('Your private kitchen',`<p>Signed in as ${esc(user.email)}</p><button id="signout">Sign out</button>`);$('#signout').onclick=async()=>{await client.auth.signOut();user=null;state=seed();$('#dialog').close();render()};return}if(client){modal('Welcome home',`<form id="login"><label>Email<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="primary">Sign in</button><small>Only your pre-created Supabase account can access the kitchen. No public sign-up is available.</small></form>`);$('#login').onsubmit=async e=>{e.preventDefault();const {error}=await client.auth.signInWithPassword(Object.fromEntries(new FormData(e.target)));if(error)return toast(error.message);$('#dialog').close();await loadCloud()};return}modal('Connect your private kitchen',`<p>Create a Supabase project and follow <strong>README.md</strong> in the repository to create your account and run the database migration.</p><form id="connect"><label>Supabase project URL<input name="url" type="url" placeholder="https://your-project.supabase.co" required></label><label>Public publishable / anon key<input name="key" required placeholder="Public key only"></label><small>Never enter a service-role or secret key. Demo data is kept separate and is not uploaded.</small><button class="primary">Connect</button></form>`);$('#connect').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/.test(f.url))return toast('Use your HTTPS Supabase project URL.');if(f.key.startsWith('sb_secret_'))return toast('Use a public publishable key, never a secret key.');if(f.key.startsWith('ey')){try{if(JSON.parse(atob(f.key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).role!=='anon')throw Error()}catch{return toast('This is not a public anon key.')}}localStorage.setItem('kitchen-connection',JSON.stringify(f));$('#dialog').close();await initCloud(f);connection()}}
async function initCloud(config){try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.57.4');client=createClient(config.url,config.key);client.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){user=null;state=seed();version=0;render()}});state=seed();await loadCloud()}catch(e){client=null;toast('Connection unavailable: '+e.message);render()}}
async function loadCloud(){const {data:{session},error}=await client.auth.getSession();if(error){toast(error.message);return}user=session?.user||null;if(user){const {data,error}=await client.from('kitchen_data').select('data,version').eq('owner_id',user.id).single();if(error){user=null;await client.auth.signOut();toast('Kitchen unavailable. Run the owner-only SQL setup first.')}else{state=data.data;version=data.version}}render();notify()}
render();const saved=JSON.parse(localStorage.getItem('kitchen-connection')||'null'),cfg=window.KITCHEN_CONFIG;if(saved||cfg?.supabaseUrl)initCloud(saved||{url:cfg.supabaseUrl,key:cfg.supabaseKey});else notify();setInterval(()=>{if(!client||user)notify()},60000);
